package org.circus.core;

import java.io.*;
import java.util.*;

/** Native100k BSS/prefix/stale lifetime with one shared decoder and realVM.
 *All MES/NAMES/captures are self-authored; no original EXE or native I/O runs. */
public final class Pc1CodeBufferTests {
    private static int count;
    private static void check(boolean value,String text){count++;if(!value)throw new AssertionError(text);}
    private interface Work{void run()throws Exception;}
    private static void reject(Work work,String text)throws Exception{boolean failed=false;try{work.run();}catch(IOException error){failed=text==null||String.valueOf(error.getMessage()).contains(text);}check(failed,"Reject "+text);}
    private static byte[] join(byte[]...pieces)throws IOException{ByteArrayOutputStream out=new ByteArrayOutputStream();for(byte[] piece:pieces)out.write(piece);return out.toByteArray();}
    private static byte[] words(int opcode,int...args){byte[] raw=new byte[1+args.length*2];raw[0]=(byte)opcode;for(int n=0;n<args.length;n++){raw[n*2+1]=(byte)args[n];raw[n*2+2]=(byte)(args[n]>>>8);}return raw;}
    private static byte[] source(byte[]...raw)throws IOException{return join(new byte[]{0,0,0,0,0x63,0x20},join(raw));}
    private static MesScript script(String name,byte[]...raw)throws IOException{return new MesScript(name,source(raw),Profiles.get("dcpc-2063"));}
    private static byte[] save(Pc1CodeBuffer owner)throws IOException{ByteArrayOutputStream bytes=new ByteArrayOutputStream();owner.save(new DataOutputStream(bytes));return bytes.toByteArray();}
    private static final class Fixture {
        final Map<String,byte[]> files=new HashMap<>();final CircusResources resources;
        Fixture(byte[] start,byte[] next)throws IOException{
            files.put("AdvData/DAT/NAMES.DAT",new byte[20]);files.put("AdvData/MES/START.mes",start);if(next!=null)files.put("AdvData/MES/NEXT.mes",next);
            GameResources input=new GameResources(new GameResources.Storage(){
                public Set<String> paths(){return files.keySet();}
                public byte[] read(String name,int limit)throws IOException{byte[] raw=files.get(name);if(raw==null)throw new FileNotFoundException(name);if(raw.length>limit)throw new IOException("Fixture limit");return raw.clone();}
                public Archive.Source source(String name)throws IOException{final byte[] raw=read(name,Integer.MAX_VALUE);return new Archive.Source(){public long size(){return raw.length;}public byte[] read(long at,int length)throws IOException{Binary.range(at,length,raw.length);return Arrays.copyOfRange(raw,(int)at,(int)at+length);}};}
            });resources=new CircusResources(input,Profiles.get("dcpc-2063"));
        }
        PcHost host()throws IOException{PcHost h=new PcHost(resources,TextCodec.identity());h.loadNativeSettings(Pc1NativeSettings.currentChsDefaults().nativeBytes());h.nativeFrameCapture=()->UiCapture.pixels(1,1,new int[]{0xff010203});return h;}
        MesVm vm(PcHost host)throws IOException{return new MesVm(resources.scripts(),host,"START");}
    }
    public static int run()throws Exception{
        count=0;Pc1CodeBuffer owner=Pc1CodeBuffer.zeroBss();check(owner.bytes().length==100000&&Binary.sha256(owner.bytes()).equals("9192c25b734fcbadbe32dadc28089c60db0e39f90cc20ce2e5733f57261acc0c"),"PE virtual zero initialization grants all100000 known code bytes");check(!owner.loaded()&&owner.loadedBytes()==0&&owner.generation()==0,"zero BSS does not invent a loaded source identity");
        byte[] first=source(new byte[]{1,77,88,0,0,0});MesScript a=new MesScript("A",first,Profiles.get("dcpc-2063"));owner.load(a);MesScript av=a.nativeView(owner);check(owner.loadedBytes()==8&&owner.generation()==1&&owner.loadedName().equals("A")&&owner.sourceSha256().equals(a.sha256),"loader records original file identity and actual code-prefix length");
        MesScript b=script("B",new byte[]{0});owner.load(b);MesScript bv=b.nativeView(owner);MesScript.Record stop=bv.fetchRecord(bv.firstOffset);check(stop.opcode==0&&!stop.terminalFragment&&Arrays.equals(stop.args,new int[]{77,88}),"one-byte STOP uses actual retained prior-prefix operands, not newly padded zeros");check(b.originalLength()==7&&b.length()==7&&bv.length()==100004&&bv.originalLength()==7&&bv.sha256.equals(b.sha256),"native code view extends memory authority without rewriting original file/hash/header identity");
        reject(()->av.rawOpcode(av.firstOffset),"different loaded source generation");check(owner.loadedBytes()==3&&owner.readU8(3)==77&&owner.readU8(4)==88,"shorter load overwrites only its three-byte prefix");
        Pc1CodeBuffer fresh=Pc1CodeBuffer.zeroBss();fresh.load(b);MesScript freshView=b.nativeView(fresh);check(Arrays.equals(freshView.fetchRecord(freshView.firstOffset).args,new int[]{0,0}),"the same short file sees real BSS zeros only on a fresh owner");
        MesScript markerOnly=script("EMPTY");check(markerOnly.records().isEmpty(),"native marker-only loader admission does not require an eager code record");fresh.load(markerOnly);check(markerOnly.nativeView(fresh).fetchRecord(markerOnly.firstOffset).opcode==0,"marker-only read leaves known prior/BSS code bytes available for fetch");
        MesScript incomplete=script("PARTIAL",new byte[]{0x5c,1,0,2,0,3,0,4,0,0x4b,'A'});check(!incomplete.staticIndexComplete(),"truncated physical-source index does not falsely reject native marker admission");Pc1CodeBuffer tail=Pc1CodeBuffer.zeroBss();tail.load(incomplete);MesScript nativePartial=incomplete.nativeView(tail);MesScript.Instruction recovered=nativePartial.instruction(nativePartial.firstOffset);check(recovered.stringPayload.bytes.length==1&&recovered.stringPayload.bytes[0]=='A'&&recovered.next==incomplete.originalLength()+1,"the one decoder consumes a genuine known BSS terminator after the source prefix");
        MesScript mutable=script("MUTABLE",words(0x58,0,0,11,0),new byte[3]);Pc1CodeBuffer code=Pc1CodeBuffer.zeroBss();code.load(mutable);MesScript view=mutable.nativeView(code);check(view.fetchRecord(view.firstOffset).opcode==0x58,"original indexed record is initially visible");code.writeU8(2,0);check(view.fetchRecord(view.firstOffset).opcode==0&&view.fetchRecord(view.firstOffset).end==view.firstOffset+3&&mutable.fetchRecord(mutable.firstOffset).opcode==0x58,"self-modified opcode bypasses cached source framing without modifying the original source");code.requireSource(mutable);check(code.sourceSha256().equals(mutable.sha256),"source identity remains original even when writable loaded prefix differs");
        MesScript labels=script("LABELS",new byte[]{0x32,'o','l','d',0,0,0,0});code.load(labels);MesScript labelsView=labels.nativeView(code);code.writeBytes(3,new byte[]{'n','e','w'});check(labelsView.requiredLabel(new byte[]{'n','e','w'})==labelsView.firstOffset&&labelsView.label(new byte[]{'o','l','d'})==null,"native label scan reads the same mutable code bytes rather than a stale label map");
        byte[] serialized=save(code);Pc1CodeBuffer decoded=Pc1CodeBuffer.load(new DataInputStream(new ByteArrayInputStream(serialized)));check(Arrays.equals(serialized,save(decoded))&&Arrays.equals(code.bytes(),decoded.bytes()),"P1CB roundtrips complete known BSS, stale tail, writable prefix and original identity");decoded.requireSource(labels);check(labels.nativeView(decoded).label(new byte[]{'n','e','w'})==labels.firstOffset,"restored self-modified prefix is accepted without an invented original-prefix equality check");
        byte[] exposed=decoded.bytes();exposed[3]=0;check(decoded.readU8(3)=='n',"code byte export is detached");Pc1CodeBuffer copied=decoded.copy();copied.writeU8(99999,257);check(copied.readU8(99999)==1&&decoded.readU8(99999)==0,"copy and last-byte low8 store retain distinct owners");copied.copyFrom(decoded);check(Arrays.equals(save(copied),save(decoded)),"full owner copy preserves identity, generations and all bytes");byte[] input={9,8};copied.writeBytes(99998,input);input[0]=0;check(copied.readU8(99998)==9,"raw code prefix write does not retain an input alias");
        byte[] before=save(copied);reject(()->copied.writeBytes(99999,new byte[2]),"outside known100000");reject(()->copied.readU8(-1),"outside known100000");reject(()->copied.readU8(100000),"outside known100000");check(Arrays.equals(before,save(copied)),"failed boundary preflight does not partially mutate code or revision");reject(()->copied.requireSource(b),"identity mismatch");
        byte[] huge=new byte[100020];Arrays.fill(huge,(byte)'A');MesScript capped=script("CAP",huge);copied.load(capped);check(copied.loadedBytes()==100000&&copied.readU8(99999)=='A',"native load reads at most100000 bytes even when original file is larger");
        byte[] stable=save(copied);MesScript other=new MesScript("OTHER",new byte[]{0,0,0,0,0x69,0x57,0,0,0},Profiles.get("dc2pc-5769"));reject(()->copied.load(other),"native2063");check(Arrays.equals(stable,save(copied)),"invalid target profile leaves the caller buffer untouched");
        reject(()->new MesScript("TRUNCATED",new byte[]{0,0,0,0,0x63},Profiles.get("dcpc-2063")),null);reject(()->new MesScript("HEAD",new byte[]{1,0,0,0,0x63,0x20},Profiles.get("dcpc-2063")),null);reject(()->new MesScript("COUNT",new byte[]{-1,-1,-1,127,0x63,0x20},Profiles.get("dcpc-2063")),"header count");
        Fixture markerFixture=new Fixture(source(),null);PcHost markerHost=markerFixture.host();MesVm markerVm=markerFixture.vm(markerHost);check(markerVm.run(1)==MesVm.Status.HALTED&&markerHost.pc1.nativeArgument0()==0&&markerHost.pc1.nativeArgument1()==0&&markerHost.readNativeCodePc()==2,"actual native host executes marker-only source using its initial known BSS operands");
        Fixture loading=new Fixture(source(new byte[]{0x36,'N','E','X','T',0}),source(new byte[]{0}));PcHost host=loading.host();MesVm vm=loading.vm(host);check(vm.run(1)==MesVm.Status.RUNNING&&vm.scriptName().equals("NEXT")&&host.pc1.codeBuffer().loadedBytes()==3,"real36 replaces only NEXT's prefix and installs its immutable metadata");byte[] during=vm.snapshot();check(host.pc1.codeBuffer().readU8(3)=='N'&&host.pc1.codeBuffer().readU8(4)=='E',"real short target retains bytes from caller resource name");PcHost restored=loading.host();MesVm resumed=loading.vm(restored);resumed.restore(during);check(Arrays.equals(during,resumed.snapshot())&&restored.pc1.codeBuffer().readU8(3)=='N',"newVM restore binds saved complete code owner without reload or fresh-zero padding");check(resumed.run(1)==MesVm.Status.HALTED&&restored.pc1.nativeArgument0()=='N'&&restored.pc1.nativeArgument1()=='E',"real terminal fragment fetch observes exact old caller tail after portable restore");
        Fixture self=new Fixture(source(words(0x58,-2321,55,0,0),words(0x58,0,0,77,0),new byte[3]),null);PcHost selfHost=self.host();MesVm selfVm=self.vm(selfHost);String originalSha=self.resources.scripts().script("START").sha256;check(selfVm.run(1)==MesVm.Status.RUNNING&&selfHost.pc1.codeBuffer().readU8(11)==0,"actual negative ordinary MES setter can modify next opcode in the known code owner");byte[] selfSave=selfVm.snapshot();PcHost selfRestored=self.host();MesVm selfNext=self.vm(selfRestored);selfNext.restore(selfSave);check(Arrays.equals(selfSave,selfNext.snapshot())&&selfRestored.script.sha256.equals(originalSha),"self-modified loaded prefix survives snapshot while original library identity remains fixed");check(selfNext.run(1)==MesVm.Status.HALTED&&selfNext.variables.read(0,0)==0&&selfRestored.readNativeCodePc()==11,"next fetch decodes modified STOP instead of cached nine-byte variable record");
        Fixture failing=new Fixture(source(new byte[]{0x36,'N','O','P','E',0}),null);PcHost failedHost=failing.host();MesVm failedVm=failing.vm(failedHost);byte[] caller=save(failedHost.pc1.codeBuffer());check(failedVm.run(1)==MesVm.Status.FAULT&&Arrays.equals(caller,save(failedHost.pc1.codeBuffer())),"failed target lookup cannot pollute the caller's code bytes or loaded identity before native load activation");
        byte[] wrong=serialized.clone();wrong[7]=2;reject(()->Pc1CodeBuffer.load(new DataInputStream(new ByteArrayInputStream(wrong))),"state format");reject(()->Pc1CodeBuffer.load(new DataInputStream(new ByteArrayInputStream(Arrays.copyOf(serialized,serialized.length-1)))),null);
        return count;
    }
    public static void main(String[] args)throws Exception{System.out.println("PASS "+run()+" PC1 canonical code-buffer assertions");}
}
